import { createContext } from "react"

import type { TimelineContextValue } from "./timeline.types"

export const TimelineContext = createContext<TimelineContextValue>({ variant: "line", size: "md" })

"use client"

import { useMemo } from "react"
import { Timeline as TimelineRoot } from "@ui-sdk/react/timeline"

import { cn } from "@/lib/cn"

import { TimelineContext } from "./timeline.constants"
import type { TimelineProps } from "./timeline.types"
import { timelineClasses } from "./timeline.variants"

export function Timeline({ variant = "line", size = "md", appear = false, className, ...props }: TimelineProps) {
  const context = useMemo(() => ({ variant, size }), [variant, size])
  return (
    <TimelineContext value={context}>
      <TimelineRoot
        data-variant={variant}
        data-size={size}
        data-appear={appear || undefined}
        className={cn(timelineClasses(variant, size), className)}
        {...props}
      />
    </TimelineContext>
  )
}

import type { ComponentProps, ReactNode } from "react"
import type { Collapsible, CollapsiblePanel, CollapsibleTrigger } from "@ui-sdk/react/collapsible"
import type { PartProps } from "@ui-sdk/react/primitive"
import type {
  Timeline as TimelineRoot,
  TimelineConnector as TimelineConnectorPart,
  TimelineDescription as TimelineDescriptionPart,
  TimelineItem as TimelineItemPart,
  TimelineMarker as TimelineMarkerPart,
  TimelineTime as TimelineTimePart,
  TimelineTitle as TimelineTitlePart,
} from "@ui-sdk/react/timeline"

import type { TooltipContentProps, TooltipProps } from "@/components/ui/tooltip/tooltip.types"
import type { IntentColor } from "@/lib/tokens.types"

/** Every intent color defined in the tokens. */
export type TimelineColor = IntentColor

/**
 * Where an event stands. `complete` happened and went well, `failed` happened with an error,
 * `current` is happening now, `upcoming` is still to come. Each has its own color.
 */
export type TimelineStatus = "complete" | "failed" | "current" | "upcoming"

/** `line`: markers joined by a line, content beside or under them. `tiles`: each event is a card with its content inside. */
export type TimelineVariant = "line" | "tiles"

/** `sm`: small dots or compact tiles. `md`: markers with room for an icon. `lg`: big markers or tall tiles. */
export type TimelineSize = "sm" | "md" | "lg"

/** `circle` for dots and steps; `square` for tiles. */
export type TimelineMarkerShape = "circle" | "square"

/** `solid` fills the marker, `soft` tints it with a colored edge, `outline` draws only the edge. */
export type TimelineMarkerVariant = "solid" | "soft" | "outline"

export type TimelineContextValue = {
  variant: TimelineVariant
  size: TimelineSize
}

export type TimelineProps = Omit<ComponentProps<typeof TimelineRoot>, "className"> & {
  className?: string
  /** Defaults to "line". In a horizontal `tiles` timeline the cards share the row equally. */
  variant?: TimelineVariant
  /** Scales markers, connectors, tiles and gaps. Defaults to "md". */
  size?: TimelineSize
  /**
   * Staggers the events in on first paint, one after another. Inside a `TimelineCollapsiblePanel`
   * they stagger in every time it opens, whatever this is. Off under reduced motion.
   */
  appear?: boolean
}

export type TimelineItemProps = Omit<ComponentProps<typeof TimelineItemPart>, "className" | "color" | "status"> & {
  className?: string
  /**
   * Where the event stands. `current` sets `aria-current="step"` and takes the tab stop; `failed`
   * counts as done for ui-sdk (it happened) and shows as `data-status="failed"`.
   */
  status?: TimelineStatus
  /**
   * Overrides the status color. Defaults from `status`: `complete` success, `failed` error,
   * `current` warning, `upcoming` muted, none primary.
   */
  color?: TimelineColor
}
/** The tooltip settings a marker passes through. For anything else, compose `Tooltip` and `TooltipTrigger` yourself. */
export type TimelineTooltipOptions = Pick<TooltipProps, "delay" | "toggleable"> &
  Pick<TooltipContentProps, "side" | "align" | "sideOffset" | "arrow" | "className">

export type TimelineMarkerProps = Omit<ComponentProps<typeof TimelineMarkerPart>, "className" | "children"> & {
  className?: string
  /** An icon or a short label inside the marker. Decorative: say the status in the title too. */
  children?: ReactNode
  /** Defaults to "circle". */
  shape?: TimelineMarkerShape
  /** Defaults from the event's status: `complete` solid, `current` soft, `upcoming` outline, none solid. */
  variant?: TimelineMarkerVariant
  /** Rings the marker, for a live step. Off when the person prefers reduced motion. */
  pulse?: boolean
  /**
   * Extra info in a tooltip. The marker becomes a focusable button; Tab reaches it after its event,
   * and a press toggles the tip on touch screens.
   */
  tooltip?: ReactNode
  /**
   * Accessible name of the marker's button. Without it the tooltip names the button, so a
   * plain-text tooltip is enough; pass one when the tooltip is rich content.
   */
  tooltipLabel?: string
  tooltipOptions?: TimelineTooltipOptions
}

export type TimelineConnectorProps = Omit<ComponentProps<typeof TimelineConnectorPart>, "className"> & {
  className?: string
}

export type TimelineContentProps = {
  className?: string
} & Omit<PartProps<"div">, "className">

export type TimelineTitleProps = Omit<ComponentProps<typeof TimelineTitlePart>, "className" | "children"> & {
  className?: string
  children?: ReactNode
}

export type TimelineTimeProps = Omit<ComponentProps<typeof TimelineTimePart>, "className" | "children"> & {
  className?: string
  children?: ReactNode
}

export type TimelineDescriptionProps = Omit<ComponentProps<typeof TimelineDescriptionPart>, "className" | "children"> & {
  className?: string
  children?: ReactNode
}

export type TimelineCollapsibleProps = Omit<ComponentProps<typeof Collapsible>, "className"> & {
  className?: string
}

export type TimelineCollapsibleTriggerProps = Omit<ComponentProps<typeof CollapsibleTrigger>, "className"> & {
  className?: string
}

export type TimelineCollapsiblePanelProps = Omit<ComponentProps<typeof CollapsiblePanel>, "className" | "children"> & {
  /** Classes for the padded box inside the panel. */
  className?: string
  children?: ReactNode
}

export type TimelineStackProps = {
  className?: string
  /** `TimelineStackItem`s, in the same order as the events they summarize. */
  children?: ReactNode
} & Omit<PartProps<"span">, "className" | "children">

export type TimelineStackItemProps = {
  /** Defaults from `status`, like a `TimelineItem`. */
  color?: TimelineColor
  status?: TimelineStatus
  /** Defaults to "circle". */
  shape?: TimelineMarkerShape
  className?: string
} & Omit<PartProps<"span">, "className" | "color" | "children">

export type TimelineLeaderProps = {
  className?: string
} & Omit<PartProps<"span">, "className" | "children">

import type {
  TimelineColor,
  TimelineMarkerShape,
  TimelineMarkerVariant,
  TimelineSize,
  TimelineStatus,
  TimelineVariant,
} from "./timeline.types"

// Each color sets three local variables the parts read:
// --timeline-color (fill), --timeline-fg (text on the fill), --timeline-accent (edges, lines and text
// on light fills: the intent's -text token, which keeps contrast where the fill wouldn't).
export const timelineColorClasses = {
  primary: "[--timeline-color:var(--primary)] [--timeline-fg:var(--primary-foreground)] [--timeline-accent:var(--primary-text)]",
  secondary: "[--timeline-color:var(--secondary)] [--timeline-fg:var(--secondary-foreground)] [--timeline-accent:var(--secondary-text)]",
  muted: "[--timeline-color:var(--muted)] [--timeline-fg:var(--muted-text)] [--timeline-accent:var(--muted-text)]",
  info: "[--timeline-color:var(--info)] [--timeline-fg:var(--info-foreground)] [--timeline-accent:var(--info-text)]",
  warning: "[--timeline-color:var(--warning)] [--timeline-fg:var(--warning-foreground)] [--timeline-accent:var(--warning-text)]",
  success: "[--timeline-color:var(--success)] [--timeline-fg:var(--success-foreground)] [--timeline-accent:var(--success-text)]",
  error: "[--timeline-color:var(--error)] [--timeline-fg:var(--error-foreground)] [--timeline-accent:var(--error-text)]",
} satisfies Record<TimelineColor, string>

// One meaning per color: done well, done with an error, happening now, still to come.
export const timelineStatusColors = {
  complete: "success",
  failed: "error",
  current: "warning",
  upcoming: "muted",
} satisfies Record<TimelineStatus, TimelineColor>

// --timeline-marker sizes the marker; --timeline-line is the title's line height, which the marker
// centers on in a vertical line timeline; --timeline-gap spaces the events.
const timelineLineSizeClasses = {
  sm: "[--timeline-marker:--spacing(3)] [--timeline-gap:--spacing(4)]",
  md: "[--timeline-marker:--spacing(7)] [--timeline-gap:--spacing(6)]",
  lg: "[--timeline-marker:--spacing(14)] [--timeline-gap:--spacing(4)]",
} satisfies Record<TimelineSize, string>

// --timeline-tile is a tile's least height, --timeline-tile-width the narrowest it gets before the
// row wraps.
const timelineTileSizeClasses = {
  sm: "gap-1.5 [--timeline-marker:--spacing(3.5)] [--timeline-tile:--spacing(14)] [--timeline-tile-width:--spacing(26)]",
  md: "gap-2 [--timeline-marker:--spacing(4)] [--timeline-tile:--spacing(20)] [--timeline-tile-width:--spacing(28)]",
  lg: "gap-3 [--timeline-marker:--spacing(5)] [--timeline-tile:--spacing(28)] [--timeline-tile-width:--spacing(36)]",
} satisfies Record<TimelineSize, string>

const timelineBaseClasses = "group/timeline relative min-w-0 [--timeline-line:--spacing(5)]"

// A line keeps one row of equal columns. Tiles fill the width equally too, but wrap onto more rows
// (auto-fit) when they'd get narrower than --timeline-tile-width, so text stays readable on phones.
const timelineLayoutClasses = {
  line: "data-[orientation=horizontal]:grid data-[orientation=horizontal]:auto-cols-fr data-[orientation=horizontal]:grid-flow-col",
  tiles:
    "data-[orientation=horizontal]:grid data-[orientation=horizontal]:grid-cols-[repeat(auto-fit,minmax(min(100%,var(--timeline-tile-width)),1fr))]",
} satisfies Record<TimelineVariant, string>

export const timelineClasses = (variant: TimelineVariant, size: TimelineSize) =>
  [
    timelineBaseClasses,
    "data-[orientation=vertical]:flex data-[orientation=vertical]:flex-col",
    timelineLayoutClasses[variant],
    variant === "tiles" ? timelineTileSizeClasses[size] : timelineLineSizeClasses[size],
  ].join(" ")

// Entrance, shared by both variants: on first paint with `appear`, and every time a
// TimelineCollapsiblePanel opens. Each event waits its turn through --timeline-index, which ui-sdk
// writes on every item. In a panel, --timeline-handoff lets the matching TimelineStackItem leave first.
const timelineItemEntranceClasses = [
  "[--timeline-delay:calc(var(--timeline-index,0)*var(--timeline-stagger,80ms))]",
  "in-data-[slot=collapsible-panel]:[--timeline-delay:calc(var(--timeline-index,0)*var(--timeline-stagger,80ms)+var(--timeline-handoff,150ms))]",
  "group-data-appear/timeline:delay-(--timeline-delay) in-data-[slot=collapsible-panel]:delay-(--timeline-delay)",
  "in-data-ending-style:delay-0 motion-reduce:transition-none",
].join(" ")

// The marker is absolutely placed at the start of the event, so the content flows beside it (vertical)
// or under it (horizontal). In a vertical timeline the smaller of marker and title line is centered on
// the other through --timeline-marker-top and the content's top padding.
const timelineLineItemClasses = [
  "group/timeline-item relative min-w-0 rounded-md outline-none",
  "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
  "data-[orientation=vertical]:[--timeline-marker-top:max(0px,calc((var(--timeline-line)-var(--timeline-marker))/2))]",
  "data-[orientation=vertical]:min-h-[calc(var(--timeline-marker)+var(--timeline-gap))] data-[orientation=vertical]:last:min-h-(--timeline-marker) data-[orientation=vertical]:data-last:min-h-(--timeline-marker)",
  "data-[orientation=vertical]:ps-[calc(var(--timeline-marker)+--spacing(3))]",
  "data-[orientation=vertical]:pt-[max(0px,calc((var(--timeline-marker)-var(--timeline-line))/2))]",
  "data-[orientation=vertical]:pb-(--timeline-gap) data-[orientation=vertical]:last:pb-0 data-[orientation=vertical]:data-last:pb-0",
  "data-[orientation=horizontal]:[--timeline-marker-top:0px]",
  "data-[orientation=horizontal]:flex data-[orientation=horizontal]:flex-col data-[orientation=horizontal]:gap-0.5",
  "data-[orientation=horizontal]:pt-[calc(var(--timeline-marker)+--spacing(2))] data-[orientation=horizontal]:pe-(--timeline-gap)",
  timelineItemEntranceClasses,
  "transition-[opacity,translate] duration-300 ease-out",
  "group-data-appear/timeline:starting:opacity-0",
  "group-data-appear/timeline:data-[orientation=vertical]:starting:-translate-y-2",
  "group-data-appear/timeline:data-[orientation=horizontal]:starting:-translate-x-3 rtl:group-data-appear/timeline:data-[orientation=horizontal]:starting:translate-x-3",
  "in-data-starting-style:opacity-0 in-data-ending-style:opacity-0",
  "data-[orientation=vertical]:in-data-starting-style:-translate-y-2",
  "data-[orientation=horizontal]:in-data-starting-style:-translate-x-3 rtl:data-[orientation=horizontal]:in-data-starting-style:translate-x-3",
  "motion-reduce:in-data-starting-style:translate-0",
].join(" ")

// A tile's look by status, shared with the stack dots that summarize it: a colored edge over a
// tint (stronger for the current event), and a dashed, empty edge for one still to come.
// Keyed on data-status, which both the item and the stack dot carry.
const timelineTileSurfaceClasses = [
  "border-2 border-(--timeline-accent) bg-background bg-linear-to-b from-(--timeline-accent)/10 to-(--timeline-accent)/10",
  "data-[status=current]:from-(--timeline-accent)/25 data-[status=current]:to-(--timeline-accent)/25",
  "data-[status=upcoming]:border-dashed data-[status=upcoming]:border-(--timeline-accent)/60 data-[status=upcoming]:from-transparent data-[status=upcoming]:to-transparent",
].join(" ")

// The event is the tile: a tinted card with its content inside. It grows out of a dot by animating
// clip-path between two inset() shapes, which interpolate smoothly (a border-radius from "full" to a
// few pixels doesn't). The ::before wash starts as a solid dot and fades to the tint as it opens.
// The inset is negative at rest so the focus ring isn't clipped.
const timelineTileItemClasses = [
  "group/timeline-item relative isolate flex min-h-(--timeline-tile) min-w-0 flex-col justify-start gap-0.5 outline-none",
  "rounded-xl",
  timelineTileSurfaceClasses,
  "group-data-[size=sm]/timeline:rounded-lg",
  // The title reserves room for the corner marker itself, so the lines under it get the full width.
  "group-data-[size=sm]/timeline:p-2 group-data-[size=md]/timeline:p-3 group-data-[size=lg]/timeline:p-4",
  "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
  "before:absolute before:inset-0 before:-z-10 before:rounded-[inherit] before:bg-(--timeline-accent) before:opacity-0",
  "before:transition-opacity before:duration-500 before:ease-out before:delay-(--timeline-delay) motion-reduce:before:transition-none",
  "[clip-path:inset(-8px_round_calc(var(--radius-xl)+8px))]",
  timelineItemEntranceClasses,
  "transition-[clip-path,translate,opacity] duration-500 ease-out",
  "in-data-starting-style:[clip-path:inset(calc(50%-8px)_calc(50%-8px)_round_8px)] in-data-starting-style:-translate-y-3 in-data-starting-style:before:opacity-100",
  "in-data-ending-style:[clip-path:inset(calc(50%-8px)_calc(50%-8px)_round_8px)] in-data-ending-style:opacity-0 in-data-ending-style:duration-200",
  "group-data-appear/timeline:starting:[clip-path:inset(calc(50%-8px)_calc(50%-8px)_round_8px)] group-data-appear/timeline:starting:before:opacity-100",
  "motion-reduce:in-data-starting-style:[clip-path:inset(-8px_round_calc(var(--radius-xl)+8px))] motion-reduce:in-data-starting-style:translate-0",
].join(" ")

export const timelineItemClasses = {
  line: timelineLineItemClasses,
  tiles: timelineTileItemClasses,
} satisfies Record<TimelineVariant, string>

export const timelineMarkerPositionClasses = {
  line: "absolute start-0 top-(--timeline-marker-top) z-10",
  tiles: "absolute end-2.5 top-2.5",
} satisfies Record<TimelineVariant, string>

const timelineMarkerShapeClasses = {
  circle: "rounded-full",
  square: "rounded-[calc(var(--timeline-marker)/4)]",
} satisfies Record<TimelineMarkerShape, string>

export const timelineMarkerRadiusClasses = timelineMarkerShapeClasses

const solid = "border-(--timeline-color) bg-(--timeline-color) text-(--timeline-fg)"
// Soft and outline paint over the page background first, so the connector never shows through.
const soft = "border-(--timeline-accent) bg-background bg-linear-to-b from-(--timeline-accent)/15 to-(--timeline-accent)/15 text-(--timeline-accent)"
const outline = "border-(--timeline-accent)/50 bg-background text-(--timeline-accent)"

const timelineMarkerVariantClasses = {
  solid,
  soft,
  outline,
} satisfies Record<TimelineMarkerVariant, string>

// Without a variant, the marker follows its event's status: done (complete or failed) solid, current
// soft, upcoming outline. Spelled out in full: Tailwind only generates classes it finds in the source.
const timelineMarkerStatusClasses = [
  solid,
  "data-current:border-(--timeline-accent) data-current:bg-linear-to-b data-current:from-(--timeline-accent)/15 data-current:to-(--timeline-accent)/15 data-current:bg-background data-current:text-(--timeline-accent)",
  "data-upcoming:border-(--timeline-accent)/50 data-upcoming:bg-background data-upcoming:text-(--timeline-accent)",
].join(" ")

